// tests/unit/helpers/mock-mint.mjs
//
// An in-process Cashu mint for the wallet tests: REAL cryptography (cashu-ts'
// own NUT-00 blind-signature / unblind primitives over a keyset generated by
// `createNewMintKeys`), REAL protocol shapes, and NO network.
//
// Why not stub the URL handlers: the invariants under test (deterministic
// secrets, counter persistence, NUT-08 change, PAID-vs-PENDING) are all about
// what the mint is ASKED and what it hands back. A mock that answered with
// canned JSON would pass a wallet that derived duplicate outputs or that read
// PENDING as success. This mock signs what it is given, so a duplicated
// (secret, keyset, counter) triple can be REFUSED exactly as a real mint refuses
// it (error 10002 "Duplicate outputs") — which is the test that matters.
//
// Every request is recorded. Tests assert on the recorded traffic, not on
// wallet-internal state, so an implementation change that keeps the wire
// behaviour honest still passes.

import {
  Amount,
  createNewMintKeys,
  createBlindSignature,
  pointFromHex,
  unblindSignature,
  verifyUnblindedSignature,
} from '@cashu/cashu-ts';

const KEYSET_SEED = new Uint8Array(32).fill(7);
const KEYSET_EXPIRY = 1_900_000_000;

const hex = (bytes) => Buffer.from(bytes).toString('hex');

/**
 * Create a mock mint.
 *
 * @param {object} [opts]
 * @param {string} [opts.url]
 * @param {number} [opts.feePpk]  input_fee_ppk advertised for the keyset
 */
export function createMockMint(opts = {}) {
  const url = opts.url || 'https://mock.mint.test';
  const feePpk = opts.feePpk ?? 0;

  const pair = createNewMintKeys(32, KEYSET_SEED, { expiry: KEYSET_EXPIRY, input_fee_ppk: feePpk });
  const keysetId = pair.keysetId;
  const pubKeysHex = Object.fromEntries(Object.entries(pair.pubKeys).map(([a, b]) => [a, hex(b)]));

  const requests = [];
  const spentSecrets = new Set();
  const issuedOutputs = new Set(); // proofs the mint has already signed, by secret
  const mintQuotes = new Map();
  const meltQuotes = new Map();
  let counter = 0;

  const json = (body) => JSON.parse(JSON.stringify(body));

  const signOutput = (blinded) => {
    const amount = Amount.from(blinded.amount).toNumber();
    const priv = pair.privKeys[String(amount)];
    if (!priv) throw mintError(11005, `no key for amount ${amount}`);
    const C_ = createBlindSignature(pointFromHex(blinded.B_), priv, blinded.id);
    return { id: blinded.id, amount: blinded.amount, C_: C_.toHex() };
  };

  const mintError = (code, detail) => {
    const error = new Error(detail);
    error.code = code;
    error.detail = detail;
    error.isMintOperationError = true;
    return error;
  };

  const spendInputs = (inputs) => {
    if (!Array.isArray(inputs)) throw mintError(10000, 'inputs must be an array');
    for (const input of inputs) {
      if (spentSecrets.has(input.secret)) throw mintError(11001, 'Token already spent.');
    }
    // Only commit after ALL inputs validate: a partial spend would be a lie.
    for (const input of inputs) spentSecrets.add(input.secret);
  };

  const signOutputs = (outputs) => {
    if (!Array.isArray(outputs)) throw mintError(10000, 'outputs must be an array');
    for (const blinded of outputs) {
      const secret = blinded.secret;
      if (secret !== undefined) {
        if (issuedOutputs.has(secret)) throw mintError(10002, 'Duplicate outputs.');
        issuedOutputs.add(secret);
      }
    }
    return outputs.map(signOutput);
  };

  const route = (path) => {
    if (path.endsWith('/v1/info')) {
      return {
        version: 'Nutshell/mock',
        name: 'mock mint',
        pubkey: hex(pair.pubKeys['1']).slice(0, 66),
        contact: [],
        nuts: {
          // honest capability advertisement: exactly what this mock implements
          4: { methods: [{ method: 'bolt11', unit: 'sat' }], disabled: false },
          5: { methods: [{ method: 'bolt11', unit: 'sat' }], disabled: false },
          7: { supported: true },
          8: { supported: true },
          9: { supported: true },
          12: { supported: false },
          20: { supported: false },
        },
      };
    }
    if (path.endsWith('/v1/keysets')) {
      return {
        keysets: [
          {
            id: keysetId,
            unit: 'sat',
            active: true,
            input_fee_ppk: feePpk,
            final_expiry: KEYSET_EXPIRY,
          },
        ],
      };
    }
    if (path.endsWith('/v1/keys')) {
      return { keysets: [{ id: keysetId, unit: 'sat', keys: pubKeysHex }] };
    }
    throw mintError(10000, `mock mint does not route ${path}`);
  };

  const handle = ({ endpoint, method = 'GET', requestBody }) => {
    requests.push({ endpoint, method, body: requestBody ? json(requestBody) : undefined });
    const path = String(endpoint).split('?')[0];

    const quoteMatch = path.match(/\/v1\/mint\/quote\/bolt11\/([^/]+)$/);
    if (quoteMatch && method === 'GET') {
      const quote = mintQuotes.get(quoteMatch[1]);
      if (!quote) throw mintError(20001, 'quote not found');
      return json({ ...quote, request: quote.request, state: quote.state });
    }
    if (/\/v1\/mint\/quote\/bolt11$/.test(path) && method === 'POST') {
      counter += 1;
      const id = `mintq-${counter}`;
      const quote = {
        quote: id,
        request: `lnbc${requestBody.amount}n1mock`,
        amount: requestBody.amount,
        unit: 'sat',
        state: opts.mintQuoteState || 'PAID',
        expiry: Math.floor(Date.now() / 1000) + 600,
      };
      mintQuotes.set(id, quote);
      return json(quote);
    }
    if (/\/v1\/mint\/bolt11$/.test(path) && method === 'POST') {
      const quote = mintQuotes.get(requestBody.quote);
      if (!quote) throw mintError(20001, 'quote not found');
      if (!opts.ignoreQuoteState && quote.state !== 'PAID') throw mintError(20001, 'quote not paid');
      const signatures = signOutputs(requestBody.outputs || []);
      return { signatures };
    }
    const meltQuoteMatch = path.match(/\/v1\/melt\/quote\/bolt11\/([^/]+)$/);
    if (meltQuoteMatch && method === 'GET') {
      const quote = meltQuotes.get(meltQuoteMatch[1]);
      if (!quote) throw mintError(20002, 'melt quote not found');
      return json(quote);
    }
    if (/\/v1\/melt\/quote\/bolt11$/.test(path) && method === 'POST') {
      counter += 1;
      const id = `meltq-${counter}`;
      const quote = {
        quote: id,
        amount: opts.meltAmount ?? 8,
        unit: 'sat',
        fee_reserve: opts.meltFeeReserve ?? 1,
        state: 'UNPAID',
        expiry: Math.floor(Date.now() / 1000) + 600,
        request: requestBody.request,
        payment_preimage: null,
        change: null,
      };
      meltQuotes.set(id, quote);
      return json(quote);
    }
    if (/\/v1\/melt\/bolt11$/.test(path) && method === 'POST') {
      const quote = meltQuotes.get(requestBody.quote);
      if (!quote) throw mintError(20002, 'melt quote not found');
      spendInputs(requestBody.inputs || []);
      const state = opts.meltState || 'PAID';
      quote.state = state;
      quote.payment_preimage = state === 'PAID' ? '00'.repeat(32) : null;
      // NUT-08: hand back whatever the blank outputs can cover, as a real mint would.
      const inputsTotal = (requestBody.inputs || []).reduce(
        (sum, input) => sum + Amount.from(input.amount).toNumber(),
        0
      );
      const overpay = inputsTotal - Amount.from(quote.amount).toNumber() - Amount.from(quote.fee_reserve).toNumber();
      const blanks = requestBody.outputs || [];
      let change = null;
      if (overpay > 0 && blanks.length) {
        change = blanks.map((blinded) => ({
          id: blinded.id,
          amount: blinded.amount,
          C_: signOutput(blinded).C_,
        }));
      }
      quote.change = change;
      return json({ ...quote, change });
    }
    if (/\/v1\/swap$/.test(path) && method === 'POST') {
      spendInputs(requestBody.inputs || []);
      return { signatures: signOutputs(requestBody.outputs || []) };
    }
    if (/\/v1\/checkstate$/.test(path) && method === 'POST') {
      return {
        states: (requestBody.ys || []).map((y) => ({
          Y: y,
          state: spentSecrets.has(y) ? 'SPENT' : 'UNSPENT',
          witness: null,
        })),
      };
    }
    if (/\/v1\/restore$/.test(path) && method === 'POST') {
      return { outputs: [], signatures: [] };
    }
    return route(path);
  };

  const request = async (args) => handle(args);

  return {
    url,
    keysetId,
    pubKeysHex,
    privKeys: pair.privKeys,
    requests,
    spentSecrets,
    mintQuotes,
    meltQuotes,
    request,
    /** Force a melt quote into a state before the wallet completes it. */
    setMeltState(quoteId, state) {
      const quote = meltQuotes.get(quoteId);
      if (quote) quote.state = state;
    },
    /** Mark a proof secret as spent, as if another wallet had redeemed it. */
    markSpent(secret) {
      spentSecrets.add(secret);
    },
    /** Count of requests to an endpoint matching `regex`. */
    count(regex) {
      return requests.filter((r) => regex.test(String(r.endpoint))).length;
    },
    lastEndpoint() {
      return requests.length ? requests[requests.length - 1].endpoint : null;
    },
  };
}

// Re-exported so a test can verify a proof the wallet holds is a real signature
// over its secret under the mock keyset — i.e. that the wallet did not fabricate.
export { verifyUnblindedSignature, unblindSignature, pointFromHex };
